package io.pacod.cms.core.data;

import lombok.Data;
import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.index.CompoundIndex;
import org.springframework.data.mongodb.core.index.CompoundIndexes;
import org.springframework.data.mongodb.core.mapping.Document;
import org.springframework.format.annotation.DateTimeFormat;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A journal issue: a cover, an editorial and an ordered list of articles, generated by the studio
 * into one PDF per language and listed at {@code /issues} once {@link IssueStatus#PUBLISHED}.
 * Called {@code JournalIssue} because {@code LayoutResolver.Issue} is a layout problem.
 *
 * <h2>{@link #articleIds} is the issue's content</h2>
 * "The articles of a month" fills the list once (published articles dated in that month, by date
 * then id); the list is then reordered or trimmed by hand. A published issue therefore never
 * changes because an article was redated or added afterwards.
 *
 * <h2>Two writers, two sets of fields</h2>
 * The studio's form sets its own fields with a targeted update; the issue job sets only
 * {@code renditions.<lang>}. Neither saves the document whole, so neither can undo the other.
 */
@Data
@Document(collection = JournalIssue.COLLECTION)
@CompoundIndexes({
        // findPublished(...) and the studio's list sort by the issue's date.
        @CompoundIndex(name = "status_date", def = "{'status': 1, 'year': -1, 'month': -1, 'number': -1}"),
        // One issue per volume and number: a second is a duplicate key, never a silent twin.
        @CompoundIndex(name = "volume_number", def = "{'volume': 1, 'number': 1}", unique = true)
})
public class JournalIssue {

    public static final String COLLECTION = "issue";

    /** How many articles one issue may hold: each is a render per language. */
    public static final int MAX_ARTICLES = 100;

    @Id
    private Integer id;

    private IssueStatus status = IssueStatus.DRAFT;

    private int volume;

    private int number;

    private int year;

    /** 1 to 12. */
    private int month;

    /** An optional theme title per language. */
    private List<TextItem> titles = new ArrayList<>();

    /** The editorial per language, HTML as written -- trusted like an article body. */
    private List<TextItem> editorials = new ArrayList<>();

    /** An {@code ImageMedia} id for the cover, or {@code null} for none. */
    private Integer coverImageId;

    private IssueSource source = IssueSource.SELECTION;

    /** In the issue's order. */
    private List<Integer> articleIds = new ArrayList<>();

    /** Null means the website's {@link PdfSettings} default. */
    private PdfFormat format;

    /** Null means the website's {@link PdfSettings} default. */
    private PdfMode mode;

    /** The languages to generate; the content's original when empty. */
    private List<String> languages = new ArrayList<>();

    /** Language → its generated PDF. */
    private Map<String, IssueRendition> renditions = new LinkedHashMap<>();

    @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME)
    private LocalDateTime createdOn;

    @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME)
    private LocalDateTime lastModifiedOn;

    @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME)
    private LocalDateTime publishedOn;

    public String title(List<String> chain) {
        return TextItems.resolve(titles, chain);
    }

    public String editorial(List<String> chain) {
        return TextItems.resolve(editorials, chain);
    }

    public String rawTitle(String lang) {
        return TextItems.find(titles, lang);
    }

    public String rawEditorial(String lang) {
        return TextItems.find(editorials, lang);
    }

    public boolean published() {
        return status == IssueStatus.PUBLISHED;
    }

    /** Never null, for a document written without the field. */
    public List<Integer> getArticleIds() {
        return articleIds == null ? List.of() : articleIds;
    }

    /** Never null, for a document written without the field. */
    public List<String> getLanguages() {
        return languages == null ? List.of() : languages;
    }

    /** Never null, for a document written without the field. */
    public Map<String, IssueRendition> getRenditions() {
        return renditions == null ? Map.of() : renditions;
    }

    /** {@link #languages}, or the content's original when none is named. */
    public List<String> languagesOrOriginal() {
        List<String> named = getLanguages();
        return named.isEmpty() ? List.of(LanguageChain.original()) : named;
    }
}
